<script lang="ts">import {goto} from '$app/navigation'; let role=$state('farmer'); let name=$state(''); function submit(){if(name)goto('/dashboard')}</script><main class="auth wrap"><p class="eyebrow">JOIN THE MARKETPLACE</p><h1>Start your<br/><em>next season.</em></h1><div class="toggle"><button class:active={role==='farmer'} onclick={()=>role='farmer'}>I'm a Farmer</button><button class:active={role==='producer'} onclick={()=>role='producer'}>I'm a Producer</button></div><form onsubmit={(e)=>{e.preventDefault();submit()}}><label>{role==='farmer'?'Farm':'Business'} name<input bind:value={name} required /></label><label>Email<input type="email" required /></label><label>Password<input type="password" required /></label><button class="btn primary">Create account ↗</button></form></main>
